def tsv_dump(
    fname: str,  # Path to TSV file
    rows: list[dict],  # List of row dictionaries
    fieldnames: list[str] | None = None  # Column names (if None, use REQUIRED_COLUMNS)
) -> None:
    """Write rows to TSV file.
    
    If fieldnames not provided, uses standard columns:
    ["Finnish", "English", "Japanese", "mp3_path", "finnish_hash", "img_path", "tags"]
    """
    if fieldnames is None:
        fieldnames = ["Finnish", "English", "Japanese", "mp3_path", "finnish_hash", "img_path", "tags"]
    
    with open(fname, "w", encoding="utf-8", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames, delimiter="\t")
        writer.writeheader()
        writer.writerows(rows)

