def tsv_en_ja(
    texts_dicts: list[dict],  # Translation dicts with Finnish, English, Japanese
    tsv: str                   # TSV file to update
) -> None:
    """Merge translations into TSV using hash matching.
    
    Updates English/Japanese columns for matching Finnish texts.
    Uses finnish_hash for matching (case-insensitive, whitespace-normalized).
    Preserves existing data (mp3_path, img_path, etc).
    
    Args:
        texts_dicts: List of dicts with keys: Finnish, English, Japanese
        tsv: Path to TSV file to update
        
    Examples:
        >>> tsv_finnish(["kissa"], "vocab.tsv")
        >>> tsv_en_ja([{"Finnish": "kissa", "English": "cat", "Japanese": "猫"}], "vocab.tsv")
    """
    # Build hash lookup: {hash: {English, Japanese}}
    translations = {}
    for d in texts_dicts:
        h = calculate_finnish_hash(d["Finnish"])
        translations[h] = {"English": d.get("English", ""), "Japanese": d.get("Japanese", "")}
    
    # Read TSV
    rows, fields = tsv_load(tsv)
    
    # Update rows with translations (match by hash)
    for row in rows:
        h = row.get("finnish_hash", "")
        if h in translations:
            # Only update if currently empty (preserve existing)
            if not row.get("English", "").strip():
                row["English"] = translations[h]["English"]
            if not row.get("Japanese", "").strip():
                row["Japanese"] = translations[h]["Japanese"]
    
    # Write back
    tsv_dump(tsv, rows, fields)

# %% ../nbs/01_tsv.ipynb #1pnpg17xy8ji
def tsv_mp3(
    tsv: str,                    # TSV file to update
    output_dir: str = "audio",   # Output directory for MP3 files
    model: str | None = None     # Piper model path (auto-downloaded if None)
) -> None:
    """Generate MP3 files and update TSV with paths (differential update).
    
    Only processes rows where mp3_path is empty and Finnish text is non-empty.
    Supports up to 100 rows (indices 00-99) due to 2-digit zero-padding.
    
    Examples:
        >>> tsv_finnish(["kissa"], "vocab.tsv")
        >>> tsv_mp3("vocab.tsv", output_dir="audio")
        # Creates: audio/vocab_00.mp3
    """
    from suomi.mp3 import text2mp3
    
    rows, fields = tsv_load(tsv)
    if len(rows) >= 100:
        raise ValueError(
            f"TSV has {len(rows)} rows but tsv_mp3() supports up to 100 "
            f"(2-digit zero-padding 00-99). Split the TSV into smaller files."
        )
    stem = Path(tsv).stem
    
    for i, row in enumerate(rows):
        finnish = row.get("Finnish", "").strip()
        if not finnish:
            continue
        if not row.get("mp3_path", "").strip():
            mp3_file = f"{output_dir}/{stem}_{i:02d}.mp3"
            text2mp3(finnish, mp3_file, model)
            row["mp3_path"] = mp3_file
    
    tsv_dump(tsv, rows, fields)

# %% ../nbs/01_tsv.ipynb #ij8apt3cxwh
def tsv_img(
    tsv: str,                           # TSV file to update
    dirs: list[str] = ["images"]        # Directories to search for images
) -> None:
    """Search for images and update TSV with paths.
    
    Searches for existing image files matching TSV filename.
    Updates only rows with empty img_path (differential update).
    Uses existing _assign_files_by_row() for file matching.
    
    File priority: row-specific .png > row-specific .jpg > common .png > common .jpg
    
    Args:
        tsv: TSV file path
        dirs: Directories to search for images
        
    Examples:
        >>> tsv_finnish(["kissa"], "vocab.tsv")
        >>> tsv_img("vocab.tsv", dirs=["images"])
    """
    rows, fields = tsv_load(tsv)
    stem = Path(tsv).stem
    
    # Find all image files
    all_imgs = ffr(dirs, [".png", ".jpg"], prefix=stem)
    
    # Assign images to rows using existing helper
    img_paths = _assign_files_by_row(all_imgs, stem, [".png", ".jpg"], len(rows))
    
    # Update only empty img_path
    for i, row in enumerate(rows):
        if not row.get("img_path", "").strip():
            row["img_path"] = img_paths[i]
    
    tsv_dump(tsv, rows, fields)

# %% ../nbs/01_tsv.ipynb #j4sm240mzn
def tsv_complete(
    tsv: str,                                       # TSV file path
    tasks: list[str] = ["translate", "mp3", "img"], # Tasks to run
    dirs: list[str] = ["audio", "images"],           # Directories for media
    model: str | None = None                        # Piper TTS model path (auto-downloaded if None)
) -> dict:
    """Run pipeline tasks on TSV (translate → mp3 → img).
    
    Each task is optional and runs only if listed in tasks.
    Results from each task are collected and returned.
    
    Args:
        tsv: TSV file path
        tasks: List of tasks to run. Options: "translate", "mp3", "img"
        dirs: Directories for media search (used by img task)
        model: Piper TTS model path for mp3 generation (auto-downloaded if None)
        
    Returns:
        Dict with results keyed by task name.
        Example: {"translate": {"translated": 2, ...}, "mp3": "done", "img": "done"}
    """
    result = {}
    
    if "translate" in tasks:
        result["translate"] = tsv_xlate(tsv)
    
    if "mp3" in tasks:
        tsv_mp3(tsv, model=model)
        result["mp3"] = "done"
    
    if "img" in tasks:
        tsv_img(tsv, dirs=dirs)
        result["img"] = "done"
    
    return result
